from functools import lru_cache

def trans(S,dr,dc): return frozenset((r+dr,c+dc) for r,c in S)
def touch(S,T): return any((r+dr,c+dc) in T for r,c in S for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
def bbox(SS):
    pts=set().union(*SS)
    rs=[r for r,c in pts];cs=[c for r,c in pts]
    return min(rs),max(rs),min(cs),max(cs)
def area(SS):
    a,b,c,d=bbox(SS);return (b-a+1)*(d-c+1)
