# Sequential nearest-to-farthest attachment: each piece chooses its own minimum-L1 contact placement.
def candidates_to_placed(i,pd):
    cand=set()
    for j,(T,oj) in pd.items():
        for dr,dc in rel6(i,j):
            off=(oj[0]+dr,oj[1]+dc)
            if valid6(i,off):cand.add(off)
    good=[]
    for off in cand:
        S=trans(shapes6[i],*off)
        if any(S&T for T,_ in pd.values()):continue
        if not any(touch(S,T) for T,_ in pd.values()):continue
        dist=abs(off[0]-orig6[i][0])+abs(off[1]-orig6[i][1])
        good.append((dist,off,S))
    return sorted(good,key=lambda x:x[0])
